  "Ardia asks before doing any of these.": "Ardia 在执行这些操作之前都会先询问。",
  "Ardia can alert you when a new meeting is about to begin. You can hide these alerts or manage how close to a meeting start they show up.": "新会议即将开始时，Ardia 可以提醒你。你可以隐藏这些提醒，或设置它们在会议开始前多久出现。",
  "Ardia can't move or resize its windows from the ardia command on this platform yet.": "在这个平台上，还不能用 ardia 命令移动 Ardia 的窗口或调整其大小。",
