  "Ardia isn't allowed to read your calendars. Allow it in System Settings › Privacy & Security › Calendars.": "Ardia 无权读取你的日历。请在“系统设置”›“隐私与安全性”›“日历”中允许。",
  "Ardia makes a new random ID. Anything sent from now on can't be tied to what was sent before, and the copy kept on this Mac is deleted.": "Ardia 会生成一个新的随机 ID。此后发送的内容无法再与之前发送的内容对应，这台 Mac 上保留的副本也会删除。",
  "Ardia needs Local Network access to find Cast devices.": "Ardia 需要本地网络权限才能查找投射设备。",
  "Ardia needs access to Bluetooth to find devices.": "Ardia 需要蓝牙权限才能查找设备。",
  "Ardia now looks the way you made it on ardia.dev. Search and privacy are still yours to choose, so those come next.": "Ardia 现在的样子与你在 ardia.dev 上的设置一致。搜索和隐私仍由你选择，接下来就是这两项。",
