  "Ardia starts fresh each launch": "Ardia 每次启动都从空白开始",
  "Ardia still doesn't have Full Disk Access. Grant it above, or use the export file below.": "Ardia 仍然没有完全磁盘访问权限。请在上方授权，或使用下方的导出文件。",
  "Ardia's Ad Blocker hides ads so pages load faster and feel cleaner.": "Ardia 的广告拦截会隐藏广告，让页面加载更快、也更干净。",
  "Ardia's config.json. Ardia applies it at launch and whenever it changes; it never writes it.": "Ardia 的 config.json。Ardia 会在启动时以及它每次变化时应用，但从不写入这个文件。",
  "Ardia's list of program names kept for its built-in plugins is missing or damaged, so no program goes on PATH": "Ardia 为内置插件保留的程序名列表缺失或已损坏，因此不会把任何程序加入 PATH",
  "Ardia's own, a password manager plugin, or none when an extension handles logins.": "可以是 Ardia 自带的、一个密码管理器插件，或在扩展程序负责登录时不使用。",
  "Ardia's report server couldn't store this right now. Your draft is kept; try again in a minute.": "Ardia 的报告服务器现在存不下这份内容。草稿已保留，请过一分钟再试。",
  "Ardia's report server has had too many reports from your network. Your draft is kept; try again in an hour.": "你的网络向 Ardia 的报告服务器提交的报告太多了。草稿已保留，请过一小时再试。",
  "Ardia's report server ran into a problem. Your draft is kept; try again in a minute.": "Ardia 的报告服务器出了问题。草稿已保留，请过一分钟再试。",
