  "For all profiles": "适用于所有配置文件",
  "For an import from Arc: how many of its Air Traffic Control rules came over and how many were left out, how many archived tabs went to Recently Cleaned, how many spaces with an icon from Arc's Icon tab got a matching emoji, and how many tab icons came from Arc's own sidebar icon cache, summed up once an hour. Never which sites, rules, tabs or spaces": "对于从 Arc 的导入：有多少条 Air Traffic Control 规则被导入、有多少被排除，有多少已归档标签页进入了“最近清理”，有多少带有来自 Arc“图标”标签页中图标的空间得到了匹配的表情符号，以及有多少标签页图标来自 Arc 自己的侧边栏图标缓存，每小时汇总一次。绝不包含具体是哪些网站、规则、标签页或空间",
  "For an update prompt that offers several usernames, the id of the one to update, from usernames": "对于提供多个用户名的更新提示，要更新的那一个的 id，取自 usernames",
  "For anything that isn't a website.": "用于一切不是网站的内容。",
  "For contains and equals": "用于包含和等于",
  "For profiles that share data with another. None do yet.": "用于与另一个配置文件共享数据的配置文件。目前还没有。",
  "For profiles that share data: the same Top Apps, one live page each.": "对于共享数据的配置文件：同一套 Top Apps，每个一个实时页面。",
  "For profiles that sync all open tabs: how many tab changes this Mac sent, how many tabs sync opened, updated and closed here, how many times a profile's tabs came back with a new window, how many syncs closed five tabs or more at once and the most tabs one sync opened or closed, summed up once an hour; and once a day, how many of your profiles sync all open tabs. Never which tabs, pages or titles": "对于同步所有打开标签页的配置文件：这台 Mac 发送了多少次标签页更改，同步在这里打开、更新和关闭了多少个标签页，有多少次某个配置文件的标签页随着新窗口恢复，有多少次同步一次关闭了五个或更多标签页，以及一次同步最多打开或关闭了多少个标签页，每小时汇总一次；并且每天一次，你有多少个配置文件在同步所有打开的标签页。绝不包含具体是哪些标签页、页面或标题",
  "For site: example.com": "用于网站：example.com",
