  "It leaves this list on all your devices, with the tabs it shared. Its data stays on it, and if it still syncs, it comes back here.": "它会连同共享的标签页，从你所有设备上的此列表中离开。数据仍留在它那里；如果它还在同步，就会回到这里。",
  "It leaves this list on all your devices. A device that still has this profile keeps it, and it comes back here.": "它会从你所有设备上的此列表中离开。仍然拥有此个人资料的设备会保留它，然后它会回到这里。",
