  "Off in Settings": "在设置中关闭",
  "Off is flatter, like Arc.": "关闭时更扁平，像 Arc。",
  "Off unless you turn it on. Either way, Ardia sends one anonymous “opened today” count a day, with no ID.": "除非你打开，否则保持关闭。无论哪种情况，Ardia 每天都会发送一次匿名的“今天已打开”计数，不含 ID。",
  "Off unless you turn it on; change it any time in Settings › Privacy & Security. Either way, Ardia sends one anonymous “opened today” count a day, with its version and macOS version and no persistent ID.": "除非你打开，否则保持关闭；可随时在设置 › 隐私与安全性中更改。无论哪种情况，Ardia 每天都会发送一次匿名的“今天已打开”计数，附带它的版本和 macOS 版本，不含持久 ID。",
  "Off, Top Apps that aren't open show a faded icon.": "关闭时，没有打开的 Top Apps 会显示淡化图标。",
  "Off, it shows only the domain.": "关闭时，只显示域名。",
  "Off. Turn Ardia on in System Settings › Privacy & Security › Passkeys Access for Web Browsers.": "已关闭。请在系统设置 › 隐私与安全性 › 网页浏览器的通行密钥访问中打开 Ardia。",
  "Offer WebKit when a video won't play": "视频无法播放时提供 WebKit",
  "Offer to set up two-factor codes a page shows in the app macOS uses for otpauth links": "页面显示出双重认证码时，提供在 macOS 用于 otpauth 链接的应用中进行设置",
  "Offers to save logins and fills saved ones.": "会提议保存登录信息，并填入已保存的登录信息。",
  "Offers to set up two-factor codes a page shows in the app macOS uses for them": "页面显示出双重认证码时，提供在 macOS 用来处理它们的应用中进行设置",
