  "Old tabs stay until you close them": "旧标签页会留着，直到你关闭它们",
  "On": "开",
  "On New Tab Only": "仅在新标签页",
  "On Windows, how many animations ran and how many of their frames came late, summed up once an hour": "在 Windows 上，运行过的动画数量，以及其中有多少帧来晚了，每小时汇总一次",
  "On Windows, how many links Ardia opened that it was started with while it wasn't running, summed up once an hour. Never which links or which app": "在 Windows 上，Ardia 未在运行时被启动并随之打开的链接数量，每小时汇总一次。绝不包含是哪些链接或哪个应用",
  "On Windows, how many pages were opened while a dialog such as a confirm or a file picker, or a pop-up menu, was open, and how many of those hadn't loaded 10 seconds later, summed up once an hour. Never which page, dialog or menu": "在 Windows 上，在确认框、文件选择器等对话框或弹出菜单打开期间打开的页面数，以及其中 10 秒后仍未加载的数量，每小时汇总一次。绝不包含是哪个页面、对话框或菜单",
  "On Windows, how many sync files waited because they were online-only or still being written, and how many online-only sync files Ardia downloaded, summed up once an hour. Never which files or what's in them": "在 Windows 上，因为仅在线或仍在写入而等待的同步文件数，以及 Ardia 下载的仅在线同步文件数，每小时汇总一次。绝不包含是哪些文件或其中的内容",
  "On Windows, how many times Ardia asked before quitting right after you confirmed closing a window's tabs, because your other window had closed meanwhile, and how many of those you cancelled, summed up once an hour": "在 Windows 上，你确认关闭某个窗口的标签页之后，因为另一个窗口已在此期间关闭，Ardia 在退出前询问的次数，以及其中你取消的次数，每小时汇总一次",
  "On Windows, how many times the command bar put back a letter its text field had dropped while you typed, summed up once an hour. Never what you typed": "在 Windows 上，命令栏在你输入时把文本框丢掉的字母放回去的次数，每小时汇总一次。绝不包含你输入的内容",
  "On Windows, when Ardia opens: how long it waited for its previous copy to finish closing, how many of its last starts didn't finish, whether it set your last session aside because of them, and whether another copy of Ardia still held your profile when it started": "在 Windows 上，Ardia 打开时：等待上一个副本完成关闭用了多久，最近有多少次启动没有完成，是否因此把上次会话搁置一旁，以及启动时是否还有另一个 Ardia 副本占着你的个人资料",
