  "Pages and Picture in Picture videos can show private things like email, messages or bank details. Only include them if nothing sensitive is on screen. Tab names, addresses and what Ardia itself shows about a page, like suggestions and media controls, always show. WebKit pages with audio or video, where streaming services play, stay black. You'll watch it before it's sent.": "页面和画中画视频可能会显示电子邮件、消息或银行明细等隐私内容。请仅在屏幕上没有敏感内容时包含它们。标签页名称、地址，以及 Ardia 本身显示的页面信息（例如建议和媒体控件）始终会显示。有音频或视频的 WebKit 页面（流媒体服务在此播放）会保持黑屏。发送之前你会先看到内容。",
