  "This profile will share your cookies, logins, passwords, extensions, bookmarks and history with your current profile. Tabs stay separate.": "此配置文件会与你当前的配置文件共享 Cookie、登录信息、密码、扩展、书签和历史记录。标签页仍然分开。",
