  "WebKit Pages": "WebKit 页面",
  "WebKit isn't part of Ardia on this platform, so pages always open in Chromium": "在这个平台上，WebKit 不属于 Ardia，所以页面始终在 Chromium 中打开",
  "WebKit pages": "WebKit 页面",
  "WebKit pages can't use passkeys until Apple grants Ardia its browser passkey entitlement. Sign in with a passkey in Chromium meanwhile.": "在 Apple 授予 Ardia 浏览器通行密钥权限之前，WebKit 页面不能使用通行密钥。这期间请在 Chromium 里用通行密钥登录。",
  "WebKit pages check addresses against Google's or Tencent's Safe Browsing lists and warn before a deceptive site opens.": "WebKit 页面会用 Google 或腾讯的安全浏览名单核对地址，并在欺诈网站打开之前发出警告。",
