  "What to sync.": "要同步什么。",
  "What you give the ardia command: addresses, selectors, typed text, scripts, notes or paths": "你交给 ardia 命令的内容：地址、选择器、输入的文字、脚本、备注或路径",
  "What you see when you open a tab.": "打开标签页时你会看到的内容。",
  "What you type": "你输入的内容",
  "What's Sent": "发送了什么",
  "What's new": "新功能",
  "What's new in Ardia": "Ardia 的新功能",
  "What's sent and what's kept on this computer.": "会发送什么，以及留在这台电脑上的是什么。",
  "WhatsApp": "WhatsApp",
  "When Ardia quits": "Ardia 退出时",
  "When a Chromium page can't play protected video, Ardia offers to open it in WebKit.": "当 Chromium 页面播不了受保护视频时，Ardia 会提议用 WebKit 打开它。",
  "When a page's first translation pass ends: how long it took, how long until the first text changed, how many passages it translated, how many styled passages had to be translated piece by piece because the answer didn't map back onto their parts, and whether it finished, stopped or failed. Never the page or its text": "页面第一轮翻译结束时：花了多久、第一处文字多久后发生变化、翻译了多少段、有多少带样式的段落因为结果对不回各个部分而必须一段段翻译，以及是完成、停止还是失败。绝不包含页面本身或其中的文字",
  "When a press on the window's title strip or a window move holds the pointer for 5 seconds or more: which of the two it was, whether it was still holding when noticed and whether a mouse button was still down. At most 10 per session, never which window or page": "按住窗口标题栏，或移动窗口时指针按住达到 5 秒或更久：是这两种里的哪一种、被注意到时是否还按着、鼠标按键是否仍然按下。每次使用最多 10 次，绝不包含是哪个窗口或页面",
  "When battery is low": "电池电量低时",
  "When main starts; worked out from contributes when left out": "main 启动时；省略时根据 contributes 推断",
  "When unplugged": "未接入电源时",
  "When you click a link that would open a new tab.": "当你点开会打开新标签页的链接时。",
  "When you import from a Chrome-family browser or Arc: which browser it was, whether its search engine was one Ardia has built in, one of your own, the browser's own default or one Ardia couldn't use, whether that changed Ardia's search engine, and whether Ardia kept the one you chose and offered the browser's instead, once per import, and how many times you took that offer, summed up once an hour. Never which search engine, its name or its address": "从 Chrome 系列浏览器或 Arc 导入时：是哪种浏览器；它的搜索引擎是 Ardia 内置的、你自己的、该浏览器自己的默认引擎，还是 Ardia 用不了的；这有没有改掉 Ardia 的搜索引擎；以及 Ardia 有没有保留你选的那个、改为提供该浏览器的引擎。每次导入记一次，以及你接受该提议的次数，每小时汇总一次。绝不包含是哪个搜索引擎、它的名称或地址",
  "When you quit and come back?": "退出后再回来呢？",
  "When you turn Offer to save and fill passwords, Save and fill addresses or Save and fill credit cards on or off and an extension keeps it as it was: which of the three it was. Never which extension": "当你打开或关闭“提议保存并填充密码”、“保存并填充地址”或“保存并填充信用卡”，而某个扩展让它保持原样时：是这三项里的哪一项。绝不包含是哪个扩展",
  "When you turn sharing on from the New Tab question: where it was shown and on how many New Tab pages it was shown first": "当你从新标签页的提问里打开共享时：它显示在哪里，以及之前先在多少个新标签页上显示过",
  "Where a link from an app would open now, as the Settings pane's tester shows it": "来自应用的链接现在会在哪里打开，与设置面板里的测试器所显示的一致",
  "Where a profile saves downloads and whether it asks": "配置文件把下载存到哪里，以及会不会询问",
  "Where a tab lands when you open it.": "打开标签页时，它会落在哪里。",
  "Where a window is on screen: its frame, whether it's zoomed, full screen or in the Dock, and its display": "窗口在屏幕上的位置：其边框、是否已缩放、是否全屏或位于程序坞中，以及所在的显示器",
  "Where are you coming from?": "你从哪里来？",
  "Where do links from other apps open?": "来自其他应用的链接在哪里打开？",
  "Where do new tabs go?": "新标签页放在哪里？",
  "Where do your tabs go?": "你的标签页放在哪里？",
  "Where downloaded files are saved.": "下载文件的保存位置。",
  "Where in the plugin's page to open, like /history": "插件页面中要打开的位置，例如 /history",
  "Where it goes: an http or https URL": "目标地址：一个 http 或 https URL",
  "Where links open when no rule decides.": "没有规则决定时，链接的打开位置。",
  "Where the New Tab row sits: top or bottom of the tab list; left out, Settings › Tabs decides": "新标签页行的位置：标签页列表的顶部或底部；若留空，则由设置 › 标签页决定",
  "Where the sidebar address field sits when the address bar is in the sidebar: top or bottom": "地址栏位于侧边栏时，侧边栏地址输入框的位置：顶部或底部",
  "Where your tabs and address bar go": "你的标签页和地址栏放在哪里",
  "Where's the address bar?": "地址栏在哪里？",
  "Whether a sent problem report's recording showed its window's Picture in Picture, and how many of Ardia's other windows over it the recording left out. Never what was in them": "已发送的问题报告录屏是否显示了该窗口的画中画，以及录屏略去了多少个叠在其上的其他 Ardia 窗口。绝不会包含其中的内容",
  "Whether it's a test build": "是否为测试版",
  "Which links": "哪些链接",
  "Which parts of the sidebar show, and where": "侧边栏显示哪些部分，以及显示在哪里",
  "Which setting": "哪项设置",
  "Which sites it can read and change: allSites or onClick; specificSites is refused until the engine can grant sites": "它可以读取和更改哪些网站：allSites 或 onClick；在引擎能够授予网站之前，specificSites 会被拒绝",
  "Which sites the extension can read and change.": "扩展程序可以读取和更改哪些网站。",
  "While a program drives Ardia, the pill shows just an icon and Stop.": "当有程序在控制 Ardia 时，胶囊只显示图标和“停止”。",
  "While a window is being resized, how many size changes its page area got and how many of them it laid out again, and how many resizes were made from the window's center with Option held, summed up once an hour": "窗口正在调整大小时，页面区域发生了多少次尺寸变化、其中多少次重新排版，以及按住 Option 从窗口中心调整了多少次，每小时汇总一次",
  "While update checks are on, each launch also reads ardia.dev/switches.json: one small file, the same for everyone, that lets us turn off a speed-up that misbehaves. It sends no ID, no cookies and nothing about you.": "开启更新检查后，每次启动还会读取 ardia.dev/switches.json：一个对所有人都相同的小文件，让我们可以关闭行为异常的加速功能。它不发送 ID，不发送 Cookie，也不发送任何关于你的信息。",
  "Wikipedia": "维基百科",
